App.Script:

// Event counters
int clickCount = 0;
int mouseDownCount = 0;
int mouseUpCount = 0;
int longPressCount = 0;
int mouseEnterCount = 0;
int mouseLeaveCount = 0;
int contextCount = 0;
List<string> eventLog = new List<string>();
const int MAX_LOG_LINES = 20;

// Event Handlers
public void OnPrimaryButtonClick()
{
    // This is called via onclick attribute (legacy)
    // Modern way is using the event system
}

public void OnMouseDown(Nimbus.WPF.NimbusEvent evt)
{
    if (evt is Nimbus.WPF.MouseDownEvent mde)
    {
        mouseDownCount++;
        LogEvent($"👇 MouseDown @ ({mde.Mouse.X:F0}, {mde.Mouse.Y:F0})");
        UpdateStats();
    }
}

public void OnMouseUp(Nimbus.WPF.NimbusEvent evt)
{
    if (evt is Nimbus.WPF.MouseUpEvent mue)
    {
        mouseUpCount++;
        LogEvent($"👆 MouseUp @ ({mue.Mouse.X:F0}, {mue.Mouse.Y:F0})");
        UpdateStats();
    }
}

public void OnClick(Nimbus.WPF.NimbusEvent evt)
{
    if (evt is Nimbus.WPF.ClickEvent ce)
    {
        clickCount++;
        LogEvent($"🔘 CLICK! Duration: {ce.Duration:F0}ms");
        UpdateStats();
    }
}

public void OnLongPress(Nimbus.WPF.NimbusEvent evt)
{
    if (evt is Nimbus.WPF.LongPressEvent lpe)
    {
        longPressCount++;
        LogEvent($"⏱️ LONG PRESS! Held: {lpe.ElapsedMs:F0}ms");
        UpdateStats();
    }
}

public void OnMouseEnter(Nimbus.WPF.NimbusEvent evt)
{
    if (evt is Nimbus.WPF.MouseEnterEvent mee)
    {
        mouseEnterCount++;
        LogEvent($"↗️ MouseEnter");
        UpdateStats();
    }
}

public void OnMouseLeave(Nimbus.WPF.NimbusEvent evt)
{
    if (evt is Nimbus.WPF.MouseLeaveEvent mle)
    {
        mouseLeaveCount++;
        LogEvent($"↙️ MouseLeave");
        UpdateStats();
    }
}

public void OnContextMenuItem()
{
    contextCount++;
    LogEvent($"⊞ Context Menu Item Clicked!");
    UpdateStats();
}

public void OnClearLog()
{
    eventLog.Clear();
    clickCount = 0;
    mouseDownCount = 0;
    mouseUpCount = 0;
    longPressCount = 0;
    mouseEnterCount = 0;
    mouseLeaveCount = 0;
    contextCount = 0;
    LogEvent("📋 Log Cleared");
    UpdateStats();
}

void LogEvent(string message)
{
    string timestamp = System.DateTime.Now.ToString("HH:mm:ss.fff");
    eventLog.Insert(0, $"[{timestamp}] {message}");
    if (eventLog.Count > MAX_LOG_LINES)
        eventLog.RemoveAt(eventLog.Count - 1);
}

void UpdateStats()
{
    var root = Engine.State.ContainsKey("_rootModule") ? (Nimbus.WPF.IUIModule)Engine.State["_rootModule"] : null;

    // Update log display
    var logLabel = FindElement(root, "lbl_eventlog");
    if (logLabel is Nimbus.WPF.NimbusLabel ll)
        ll.Content = string.Join("\n", eventLog);

    // Update statistics
    UpdateLabel(root, "stat_click", $"🔘 Clicks: {clickCount}");
    UpdateLabel(root, "stat_mousedown", $"👇 MouseDown: {mouseDownCount}");
    UpdateLabel(root, "stat_mouseup", $"👆 MouseUp: {mouseUpCount}");
    UpdateLabel(root, "stat_longpress", $"⏱️ LongPress: {longPressCount}");
    UpdateLabel(root, "stat_mouseenter", $"↗️ MouseEnter: {mouseEnterCount}");
    UpdateLabel(root, "stat_mouseleave", $"↙️ MouseLeave: {mouseLeaveCount}");
    UpdateLabel(root, "stat_context", $"⊞ Context: {contextCount}");
}

void UpdateLabel(Nimbus.WPF.IUIModule root, string id, string content)
{
    var label = FindElement(root, id);
    if (label is Nimbus.WPF.NimbusLabel nl)
        nl.Content = content;
}

Nimbus.WPF.IUIModule FindElement(Nimbus.WPF.IUIModule current, string id)
{
    if (current == null) return null;
    if (current.Id == id) return current;
    foreach (var child in current.Children)
    {
        var result = FindElement(child, id);
        if (result != null) return result;
    }
    return null;
}
